psutil_proc_pidtaskinfo_oneshot(PyObject *self, PyObject *args) {
    long pid;
    struct proc_taskinfo pti;

    if (! PyArg_ParseTuple(args, "l", &pid))
        return NULL;
    if (psutil_proc_pidinfo(pid, PROC_PIDTASKINFO, 0, &pti, sizeof(pti)) <= 0)
        return NULL;

    return Py_BuildValue(
        "(ddKKkkkk)",
        (float)pti.pti_total_user / 1000000000.0,     // (float) cpu user time
        (float)pti.pti_total_system / 1000000000.0,   // (float) cpu sys time
        // Note about memory: determining other mem stats on macOS is a mess:
        // http://www.opensource.apple.com/source/top/top-67/libtop.c?txt
        // I just give up.
        // struct proc_regioninfo pri;
        // psutil_proc_pidinfo(pid, PROC_PIDREGIONINFO, 0, &pri, sizeof(pri))
        pti.pti_resident_size,  // (uns long long) rss
        pti.pti_virtual_size,   // (uns long long) vms
        pti.pti_faults,         // (uns long) number of page faults (pages)
        pti.pti_pageins,        // (uns long) number of actual pageins (pages)
        pti.pti_threadnum,      // (uns long) num threads
        // Unvoluntary value seems not to be available;
        // pti.pti_csw probably refers to the sum of the two;
        // getrusage() numbers seems to confirm this theory.
        pti.pti_csw             // (uns long) voluntary ctx switches
    );
}

std::map<int64, int64> GetMetaProtoTimes(sqlite3* db_handle) {
sqlite_utils::SQLStatement statement;
statement.prepare(
db_handle,
"SELECT metahandle, mtime, server_mtime, ctime, server_ctime FROM metas");
EXPECT_EQ(5, statement.column_count());
std::map<int64, int64> meta_times;
while (true) {
int query_result = statement.step();
if (query_result != SQLITE_ROW) {
EXPECT_EQ(SQLITE_DONE, query_result);
break;
}
int64 metahandle = statement.column_int64(0);
int64 mtime = statement.column_int64(1);
int64 server_mtime = statement.column_int64(2);
int64 ctime = statement.column_int64(3);
int64 server_ctime = statement.column_int64(4);
EXPECT_EQ(mtime, server_mtime);
EXPECT_EQ(mtime, ctime);
EXPECT_EQ(mtime, server_ctime);
meta_times[metahandle] = mtime;
}
return meta_times;
}

